--初始化地图
function BambooMgr:InitMap()
    if not self._gridePar then 
        self._gridePar = GameObject.Find("Grides")
        self._gridePar.transform.position = self._grideParPos
    end
    if not self._bambooCam then
        self._bambooCam = GameObject.Find("BambooCamera")
    end
    if not self._scenePar then
        self._scenePar = GameObject.Find("BambooScene")
    end

    local grideIds = BambooUtils.GetBambooMapPoints(self._mapId)
    if not grideIds or table.count(grideIds) < 1 then
        return
    end

    self._obstacles = {}
    self._mapGrides = {}

    local middleX = self._mapColumn * 0.5
    --local sum = 1 + self._mapColumn   --用来做坐标镜像
    for k, v in pairs(grideIds) do
        local vo = BambooUtils.GetBambooMapPointVo(v)
        if vo then
            if vo.canMove == ConstantsBamboo.GrideStatus.OBSTACLES then
                self:RefreshGrideStatus(vo, vo.canMove)
            end
            local normal = (vo.posX <= middleX and -1 or 1)

            local z = (vo.posY - 1) * ConstantsBamboo.GrideSideLength + ConstantsBamboo.PosOff
            local x = (vo.posX - 1) * ConstantsBamboo.GrideSideLength + ConstantsBamboo.PosOff
            --local offX = (vo.posX > middleX and sum - vo.posX or vo.posX)
            local offX = 0
            local y = (offX * ConstantsBamboo.GrideSideLength - ConstantsBamboo.PosOff) * math.sin(ConstantsBamboo.OffZ * Mathf.Deg2Rad)
            y = 0

            local pos = Vector3((vo.posX - 1) * ConstantsBamboo.GrideSideLength + ConstantsBamboo.PosOff, 0, (vo.posY - 1) * ConstantsBamboo.GrideSideLength + ConstantsBamboo.PosOff)
            pos = Vector3(x, -y, z)

            local gridVo = BambooMapGrideVo.New()
            gridVo._id = v
            gridVo._pos = pos
            gridVo._status = vo.canMove
            self._mapGrides[checkString(vo.posY..vo.posX)] = gridVo

            local grideLoader = self:GetLoader(ConstantsBamboo.BambooMapGridePath)
            if grideLoader.IsSuccess then
                local go = CfUtils.InstantiateGo(grideLoader.ResultObject, self._gridePar)
                go.transform.localPosition = pos
                --go.transform.localEulerAngles = Vector3(0, 0, ConstantsBamboo.OffZ * normal)

                UIEventProxy.Create(go.gameObject).onPointerClick = function(eventData)
                    self:ClickGride(gridVo._id)
                end 
                
                pos = go.transform.position
                --[[
                local lr = go:GetComponent(typeof(CS.UnityEngine.LineRenderer))
                local _offX = ConstantsBamboo.PosOff * math.cos(ConstantsBamboo.OffZ * Mathf.Deg2Rad)
                local _offY = ConstantsBamboo.PosOff * math.sin(ConstantsBamboo.OffZ * Mathf.Deg2Rad)

                --[[
                lr:SetPosition(0, Vector3(pos.x - _offX, pos.y - _offY * normal, pos.z - 0.08))
                lr:SetPosition(1, Vector3(pos.x + _offX, pos.y + _offY * normal, pos.z - 0.08))
                lr:SetPosition(2, Vector3(pos.x + _offX, pos.y + _offY * normal, pos.z + 0.08))
                lr:SetPosition(3, Vector3(pos.x - _offX, pos.y - _offY * normal, pos.z + 0.08))
                lr:SetPosition(4, Vector3(pos.x - _offX, pos.y - _offY * normal, pos.z - 0.08))
                ]]
                --[[
                lr:SetPosition(0, Vector3(pos.x - _offX, 0, pos.z - 0.08))
                lr:SetPosition(1, Vector3(pos.x + _offX, 0, pos.z - 0.08))
                lr:SetPosition(2, Vector3(pos.x + _offX, 0, pos.z + 0.08))
                lr:SetPosition(3, Vector3(pos.x - _offX, 0, pos.z + 0.08))
                lr:SetPosition(4, Vector3(pos.x - _offX, 0, pos.z - 0.08))
                ]]

                gridVo._grideGo = go
                go.name = gridVo._id
            end
        end
    end

    local go = GameObject.Find("BambooScene")
    if not isNull(go) then
        local mapVo = BambooUtils.GetBambooActivityCopyVo(self._mapId)
        local mapGo = go.transform:Find("chessboard/chessboard_01")
        local sw = mapGo.gameObject:GetComponent(typeof(CS.Game.Native.Common.MaterialSwitcher))
        sw:SwitchMaterial(checkNumber(mapVo.SceneId) - 1)
    end
    --[[
    local loader = self:GetLoader(BambooUtils.GetFloorPath(self._mapId))
    if loader and loader.IsSuccess then
        CfUtils.InstantiateGo(loader.ResultObject, self._scenePar)
    end
    ]]
    --[[
    local loader = self:GetLoader(BambooUtils.GetFloorBgPath(self._mapId))
    if loader and loader.IsSuccess then
        CfUtils.InstantiateGo(loader.ResultObject, self._scenePar)
    end
    ]]

    AStarMgr:GetInstance():InitData(self._obstacles, self._mapLine, self._mapColumn)
    local pos = BambooUtils.GetCurPlayerPos()
    if not string.isEmpty(pos) then 
        self:SetCurGride(pos)
    end

    self:InitMapEvents()
    if not self._curGride then
        GameUtils.Toast(localize("初始位置没找到！"))
    end
    self:InitFinishEvents()

    cs_coroutine.yield_return(self:InitPlayer())
    self:HandleStateTimeDown()
end

--初始化地图事件
function BambooMgr:InitMapEvents()
    local curWave = checkNumber(BambooQuestComponent:GetCurWave())
    if curWave < 0 then
        return
    end

    self:RefreshMapEvents(0, curWave)
end

--刷新地图事件
---@param fWave number fWave 起始波次  
---@param tWave number tWave 结束波次 参数要+1
function BambooMgr:RefreshMapEvents(fWave, tWave)
    fWave = checkNumber(fWave)
    tWave = checkNumber(tWave)
    if tWave < fWave then 
        return
    end
    for i = fWave + 1, tWave + 1 do
        local eventIds = BambooUtils.GetBambooMapWavePoints(self._mapId, (i - 1))
        if eventIds and table.count(eventIds) > 0 then
            --所有的事件
            for k, v in pairs(eventIds) do
                local eventVo = BambooUtils.GetBambooEventVo(v)
                if eventVo then
                    local eventId = v

                    --该事件所有的格子
                    local grideIds = CfUtils.Split(eventVo.ceilId)
                    if grideIds and table.count(grideIds) > 0 then
                        --如果第一次进入 需要读配置
                        if not self._curGride then
                            if eventVo.type == ConstantsBamboo.GrideEventType.Birth then
                                self:SetCurGride(grideIds[1])
                            end
                        end

                        for _, grideId in pairs(grideIds) do
                            local grideVo = self:GetGrideVoById(grideId)
                            self:RefreshGrideEventId(grideVo, eventId)

                            if _ == 1 then
                                self:SetGrideGo(grideVo, self:GetEventGoPath(eventVo.id))
                            end
                        end
                    end
                end
            end
        end
    end
end

function BambooMgr:GetEventGoPath(eventId)
    local vo = BambooUtils.GetBambooEventVo(eventId)
    if not vo then
        return ""
    end

    vo = BambooUtils.GetBambooEventImageMapVo(vo.model)
    if not vo then
        return ""
    end

    return vo.prefab
end

--完成的事件
function BambooMgr:InitFinishEvents()
    local t = BambooQuestComponent:GetAllPassEventId()
    if not t then
        return
    end
    for k, v in pairs(t) do
        local eventVo = BambooUtils.GetBambooEventVo(k)
        if eventVo then
            --如果是结束点通关 
            if checkNumber(eventVo.type) == ConstantsBamboo.GrideEventType.Finish then
                self._isFinish = true
            end
            self:CompleteEvent(k)
        end
    end
end

