---GetPath 获取路径
---@param fGrideVo table BambooMapGrideVo
---@param tGridVo table BambooMapGrideVo
function BambooMgr:GetPath(fGrideVo, tGridVo)
    if not fGrideVo or not tGridVo then
        return {}
    end

    local _f = BambooUtils.GetAstarVoByGride(fGrideVo)
    local _t = BambooUtils.GetAstarVoByGride(tGridVo)

    if not _f or not _t then
        return {}
    end

    local t = AStarMgr:GetInstance():FindPath(_f, _t)
    return t
end

---ClickGride 点击格子
---@param grideId number 格子id
function BambooMgr:ClickGride(grideId)
    if self._isFindPathing then
        return
    end

    local curGrideVo = self:GetCurGride()
    local grideVo = self:GetGrideVoById(grideId)

    local eventVo = BambooUtils.GetEventVoByGride(grideVo)
    local bambooEventImageMapVo
    local isBoss = false
    local fPos = grideVo._grideGo.transform.position + Vector3(-ConstantsBamboo.GrideSideLength * 0.5, 0 -ConstantsBamboo.GrideSideLength * 0.5)
    local tPos = grideVo._grideGo.transform.position + Vector3(ConstantsBamboo.GrideSideLength * 0.5, 0 -ConstantsBamboo.GrideSideLength * 0.5)

    if eventVo then
        bambooEventImageMapVo = BambooUtils.GetBambooEventImageMapVo(eventVo.model)
        isBoss = (checkNumber(eventVo.model) == ConstantsBamboo.GridShowType.BOSS)
    end

    if not curGrideVo then
        --GameUtils.Toast(localize("当前所处格子为空"))
        self:RefeshCatState(ConstantsBamboo.CatState.Stop)
        return
    elseif not grideVo then
        --GameUtils.Toast(localize("点击格子为空"))
        self:RefeshCatState(ConstantsBamboo.CatState.Stop)
        return
    --elseif self._lastTargetGride and checkString(self._lastTargetGride._id) == checkString(grideVo._id) then
        --GameUtils.Toast(localize("相同的目标点点击"))
    --    self:RefeshCatState(ConstantsBamboo.CatState.Stop)
    --    return
    elseif checkString(curGrideVo._id) == checkString(grideVo._id) then
        --GameUtils.Toast(localize("已经在目标点"))
        self:RefeshCatState(ConstantsBamboo.CatState.Stop)
        return
    elseif not isNull(eventVo) and checkNumber(eventVo.type) == ConstantsBamboo.GrideEventType.Tips and not isNull(grideVo._grideModelGo) then
        GameUtils.ThirdConfirm(eventVo.tips, bambooEventImageMapVo.icon, eventVo.tips, bambooEventImageMapVo.name, isBoss, tPos, fPos, function()
        end, function()
        end, checkNumber(eventVo.openConfirm) ~= 1)
        self:RefeshCatState(ConstantsBamboo.CatState.Stop)
        return
    elseif checkNumber(grideVo._status) == ConstantsBamboo.GrideStatus.OBSTACLES then
        --GameUtils.Toast(localize("该点为障碍物"))
        --[[
        if eventVo and bambooEventImageMapVo then
            GameUtils.ThirdConfirm(eventVo.tips, bambooEventImageMapVo.icon, eventVo.tips, bambooEventImageMapVo.name, isBoss, nil, nil, function()
            end, function()
            end, checkNumber(eventVo.openConfirm) ~= 1)
        end
        ]]
        GameUtils.Toast(eventVo.tips)
        self:RefeshCatState(ConstantsBamboo.CatState.Stop)
        return
    end
    
    --有事件
    if eventVo and bambooEventImageMapVo then
        --如果这个格子模型没了  说明被清掉了
        if isNull(grideVo._grideModelGo) then
            self:SetTargetGride(grideVo)
            return
        end

        self:FillChooseGo(grideVo)
        GameUtils.ThirdConfirm(eventVo.tips, bambooEventImageMapVo.icon, eventVo.tips, bambooEventImageMapVo.name, isBoss, tPos, fPos, function()
            self:SetTargetGride(grideVo)
        end, function()
            self:PullModelPool(ConstantsBamboo.ChooseGoPath, nil, self._ChooseGo)
            self._ChooseGo = nil
        end, checkNumber(eventVo.openConfirm) ~= 1)
    else
        self:SetTargetGride(grideVo)
    end
end

---SetCurGride 设置人物当前格子
---@param grideId table BambooMapPointVo
function BambooMgr:SetCurGride(grideId)
    self._curGride = self:GetGrideVoById(grideId)
end

---SetTargetGride 设置目标格子
---@param grideVo table BambooMapPointVo
function BambooMgr:SetTargetGride(grideVo)
    self:SignPathGride(grideVo, true)

    --寻路中
    if self._isFindPathing then
        if self._lastTargetGride then
            self:SignPathGride(self._lastTargetGride, false)
        end
        
        self._targetGride = grideVo
    else
        local gride = self:GetCurGride()
        local t = self:GetPath(gride, grideVo)

        --没路径
        if not t or table.count(t) <= 0 then
        else
            local eventVo = BambooUtils.GetEventVoByGride(grideVo)
            local bambooEventImageMapVo
            if eventVo then
                bambooEventImageMapVo = BambooUtils.GetBambooEventImageMapVo(eventVo.model)
            end
            --有事件
            if eventVo and bambooEventImageMapVo then
                --如果这个格子模型没了  说明被清掉了
                if isNull(grideVo._grideModelGo) then
                    self:FillTargetGo(grideVo)
                end
            else
                self:FillTargetGo(grideVo)
            end
        end

        self:PlayerMove(t)
    end
    self._lastTargetGride = grideVo
end

---PlayerMove 玩家移动

---@param path table 移动路径
function BambooMgr:PlayerMove(path)
    self:ClearMoveCo()
    if not path or table.count(path) <= 0 then
        self:PullModelPool(ConstantsBamboo.ChooseGoPath, nil, self._ChooseGo)
        self._ChooseGo = nil

        GameUtils.Toast(localize("无法前往目标地点"))
        self._lastTargetGride = nil
        self._targetGride = nil
        return
    end


    self._moveCo = cs_coroutine.start(function()
        self:FillFootGos(path)
        table.remove(path, #path)
        self._isFindPathing = true

        --table.insert(self._moveHistory, self._curGride._id)
        for k, v in fipairs(path) do
            --被强制停止
            if self._stopMove then
                return
            end
            local curGride = self:GetCurGride()
            --没有当前点直接退出去
            if not curGride then
                return
            end

            local vo = self:GetGrideVo(v._line, v._column)
            if not vo then
                printError("非法点")
                self._stopMove = true
                return
            end
            local fGride = self._curGride
            self:SetCurGride(vo._id)
            --self:MoveTween(fGride, vo)
            cs_coroutine.yield_return(self:PlayerMoveCo(fGride, vo))
            --移动
            coroutine.yield(Yielders.GetWaitForSeconds(ConstantsBamboo.MoveMaxTime + 0.01))

            --走完了
            self._isMoving = false
            if table.count(self._moveHistory) < 1 then
                table.insert(self._moveHistory, fGride._id)
            end
            table.insert(self._moveHistory, vo._id)
            --检查当前状态
            self:CheckCurGride()
            --self:PullModelPool(ConstantsBamboo.FootMarkPath, nil, self._footMarkGo)
            cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.001))


            if k == 1 then
                self._isFindPathing = false
                self:SignPathGride(vo)

                --清脚印
                self:ClearFootGo()
                if not isNull(self._ChooseGo) then
                    self:PullModelPool(ConstantsBamboo.ChooseGoPath, nil, self._ChooseGo)
                    self._ChooseGo = nil
                end
                if not isNull(self._targetGo) then
                    self:PullModelPool(ConstantsBamboo.TargetGoPath, nil, self._targetGo)
                    self._targetGo = nil
                end

                if not BambooUtils.IsGrideHasEvent(vo) then
                    self:RefeshCatState(ConstantsBamboo.CatState.Idle1, true)
                    BambooQuestComponent:ActivityQuestMoveReq(self._moveHistory, 0, self._activityUuid, function()
                        self._moveHistory = {}
                    end, function()
                        GameUtils.Toast(localize("寻路失败"))
                        self:BackPathOriginGride()
                    end)
                end
            end
        end
    end)
end

function BambooMgr:FillFootGos(path)
    print(table.dump(path))
    for i = 1, #path - 1 do
        local fVo = self:GetGrideVo(path[i]._line, path[i]._column)
        local tVo = self:GetGrideVo(path[i + 1]._line, path[i + 1]._column)

        self:FillFootGo(fVo, tVo)
    end

    --[[
    --最后一个
    local fVo = self:GetGrideVo(path[#path]._line, path[#path]._column)
    local tVo = self:GetGrideVo(path[#path]._line, path[#path]._column)
    self:FillFootGo(fVo, tVo, true)
    ]]
end

function BambooMgr:ClearFootGo()
    if not self._footMarkGos or table.count(self._footMarkGos) <= 0 then
        return
    end

    for k, v in fipairs(self._footMarkGos) do
        self:PullModelPool(ConstantsBamboo.FootMarkPath, nil, v)
        table.remove(self._footMarkGos, k)
    end
end

--目标点
function BambooMgr:FillTargetGo(gride)
    if not gride then
        return
    end

    self._targetGo = self:GetModelGo(ConstantsBamboo.TargetGoPath)
    if isNull(self._targetGo) then
        return
    end

    KTool.SetParent(self._targetGo, gride._grideGo, false)
    KTool.SetActive(self._targetGo, true)
    self._targetGo.transform.localPosition = Vector3(-ConstantsBamboo.PosOff, 0.01, -ConstantsBamboo.PosOff)
end

function BambooMgr:FillChooseGo(gride)
    if not gride then
        return
    end

    self._ChooseGo = self:GetModelGo(ConstantsBamboo.ChooseGoPath)
    if isNull(self._ChooseGo) then
        return
    end

    KTool.SetParent(self._ChooseGo, gride._grideGo, false)
    KTool.SetActive(self._ChooseGo, true)
    self._ChooseGo.transform.localPosition = Vector3(ConstantsBamboo.ChooseGoPosOffX, 0.01, ConstantsBamboo.ChooseGoPosOffZ)
end

function BambooMgr:FillFootGo(fGride, tGride, isEnd)
    local fPos = Vector3(fGride._pos.x, fGride._pos.y, fGride._pos.z)
    local tPos = Vector3(tGride._pos.x, tGride._pos.y, tGride._pos.z)
    local dis = tPos - fPos
    local normalDis = dis / ConstantsBamboo.MoveDis

    local normal = tGride._pos.x >= fGride._pos.x and 1 or -1

    --脚印
    local footMarkGo = self:GetModelGo(ConstantsBamboo.FootMarkPath)
    if footMarkGo then
        KTool.SetParent(footMarkGo, tGride._grideGo, false)
        KTool.SetActive(footMarkGo, true)
        local voF = BambooUtils.GetBambooMapPointVo(fGride._id)
        local voT = BambooUtils.GetBambooMapPointVo(tGride._id)
        if voF and voT then
            local angles
            --水平移动？
            local isHorizontal = (voF.posX ~= voT.posX)

            if isEnd then
                isHorizontal = self._lastMoveHorizontal
            end

            if isHorizontal then
                angles = Vector3(0, normal > 0 and 0 or 180, 0)

                footMarkGo.transform.localPosition = Vector3(-normal * ConstantsBamboo.PosOff * 2, 0.01, -normal * 0.15)
            else
                local normalY = tGride._pos.z >= fGride._pos.z and 1 or -1
                angles = Vector3(0, normalY > 0 and 270 or 90, 0)

                footMarkGo.transform.localPosition = Vector3(normalY * 0.15, 0.001, -normalY * ConstantsBamboo.PosOff * 2)
            end
            self._lastMoveHorizontal = isHorizontal

            footMarkGo.transform.localEulerAngles = angles
        end
    end
    table.insert(self._footMarkGos, footMarkGo)
end

function BambooMgr:PlayerMoveCo(fGride, tGride)
    if self._isMoving or not fGride or not tGride then
        return
    end
    self._isMoving = true
    local fPos = Vector3(fGride._pos.x, fGride._pos.y, fGride._pos.z)
    local tPos = Vector3(tGride._pos.x, tGride._pos.y, tGride._pos.z)
    local dis = tPos - fPos
    local normalDis = dis / ConstantsBamboo.MoveDis

    local normal = tGride._pos.x >= fGride._pos.x and 1 or -1
    self:RefeshCatState(ConstantsBamboo.CatState.Run, true)
    self._waitTime = 11

    local voF = BambooUtils.GetBambooMapPointVo(fGride._id)
    local voT = BambooUtils.GetBambooMapPointVo(tGride._id)
    if voF and voT then
        local angles
        --水平移动？
        local isHorizontal = (voF.posX ~= voT.posX)

        if isHorizontal then
            angles = Vector3(0, normal > 0 and 180 or 0, 0)
            self._playerGo.transform.localEulerAngles = Vector3(0, normal > 0 and 90 or -90, ConstantsBamboo.OffZ * normal)
        else
            local normalY = tGride._pos.z >= fGride._pos.z and 1 or -1
            angles = Vector3(0, normalY > 0 and 90 or 270, 0)

            self._playerGo.transform.localEulerAngles = Vector3(0, normalY > 0 and 0 or 180, ConstantsBamboo.OffZ * normal)
        end
    end

    
    self._moveFPos = fPos
    self._moveTPos = tPos
    self._moveTime = 0
    self._isCanMove = true
    --[[
    for i = 1, ConstantsBamboo.MoveDis do
        self:SetPlayerPos(fPos + normalDis * i)
        cs_coroutine.yield_return(Yielders.GetWaitForSeconds(self._moveTime / ConstantsBamboo.MoveDis))

        if i == ConstantsBamboo.MoveDis then
            self._isMoving = false
            if table.count(self._moveHistory) < 1 then
                table.insert(self._moveHistory, fGride._id)
            end
            table.insert(self._moveHistory, tGride._id)
            --检查当前状态
            self:CheckCurGride()
            self:PullModelPool(ConstantsBamboo.FootMarkPath, nil, footMarkGo)
        end
    end
    ]]

    --cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.001))
end

function BambooMgr:OnUpdate()
    if not self._isCanMove then
        return
    end

    self._moveTime = checkNumber(self._moveTime) + CS.UnityEngine.Time.deltaTime
    if self._moveFPos and self._moveTPos then
        self:SetPlayerPos(self._moveFPos + (self._moveTPos - self._moveFPos) * (self._moveTime / ConstantsBamboo.MoveMaxTime))
    end

    if self._moveTime >= ConstantsBamboo.MoveMaxTime then
        self._isCanMove = false
        self._moveTime = 0
        self._moveFPos = nil
        self._moveTPos = nil
    end
end

---MoveTween 移动动画
---@param fGride table 
---@param tGride table
function BambooMgr:MoveTween(fGride, tGride)
    if self._isMoving or not fGride or not tGride then
        return
    end
    self:ClearMoveTween()
    self._isMoving = true
    local fPos = Vector3(fGride._pos.x, fGride._pos.y, fGride._pos.z - ConstantsBamboo.PosOff)
    local tPos = Vector3(tGride._pos.x, tGride._pos.y, tGride._pos.z - ConstantsBamboo.PosOff)
    local dis = tPos - fPos

    self._moveTween = CfUtils.DoTween(self._moveTime, function(updateValue)
        self:SetPlayerPos(fPos + dis * updateValue)
    end, function()
        if table.count(self._moveHistory) < 1 then
            table.insert(self._moveHistory, fGride._id)
        end
        table.insert(self._moveHistory, tGride._id)
        self._isMoving = false
        self._waitTime = 0
        self:RefeshCatState(ConstantsBamboo.CatState.Idle1, true)
        --检查当前状态
        self:CheckCurGride()
    end, function()
        local normal = tGride._pos.x >= fGride._pos.x and 1 or -1
        self._playerGo.transform.localEulerAngles = Vector3(normal * ConstantsBamboo.PlayerRotateX, normal > 0 and 0 or 180, ConstantsBamboo.OffZ * normal)
        self:RefeshCatState(ConstantsBamboo.CatState.Run, true)
        self._waitTime = 11
    end)
end

function BambooMgr:CheckCurGride()
    local gride = self:GetCurGride()
    if not gride then
        return
    end

    --如果有事件触发
    if BambooUtils.IsGrideHasEvent(gride) then
        self:ClearMoveCo()
        self:HandleGrideEvent(gride)

        if self._lastTargetGride then
            self:SignPathGride(self._lastTargetGride)
        end
        if self._targetGride then
            self:SignPathGride(self._targetGride)
        end
        self._lastTargetGride = nil
        self._targetGride = nil

        --self:SetPlayerSpine(SpineName.idle1, true)
    --如果有新的目标点
    elseif self._targetGride then
        local t = self:GetPath(gride, self._targetGride)
        self._targetGride = nil
        if t and table.count(t) > 0 then
            self:PlayerMove(t)
        end
    else

    end
end

---BackPathOriginGride 返回上一次路径原点
function BambooMgr:BackPathOriginGride()
    table.remove(self._moveHistory, #self._moveHistory)
    BambooQuestComponent:ActivityQuestMoveReq(self._moveHistory, 0, self._activityUuid, function()
        local grideId = self._moveHistory[#self._moveHistory]
        if grideId then
            --放弃直接回原点
            self:SetPlayerPosByGrideId(grideId) 
            self:SetCurGride(grideId)
        end
        self._moveHistory = {}
        --清脚印
        self:ClearFootGo()
        self._lastTargetGride = nil
        self:RefeshCatState(ConstantsBamboo.CatState.Idle1)
    end)
end

---HandleGrideEvent 处理格子事件
function BambooMgr:HandleGrideEvent()
    if not isNull(self._ChooseGo) then
        self:PullModelPool(ConstantsBamboo.ChooseGoPath, nil, self._ChooseGo)
        self._ChooseGo = nil
    end
    if not isNull(self._targetGo) then
        self:PullModelPool(ConstantsBamboo.TargetGoPath, nil, self._targetGo)
        self._targetGo = nil
    end

    
    local grideVo = self:GetCurGride()
    local eventVo = BambooUtils.GetEventVoByGride(grideVo)
    if not eventVo then
        return
    end

    local isUnlock, unlockStr = BambooUtils.IsUnlockMapEvent(eventVo.id, self._activityUuid)
    if not isUnlock then
        GameUtils.Toast(unlockStr)
        self:BackPathOriginGride()
        return
    end

    local type = checkNumber(eventVo.type)
    --出生点
    if type == ConstantsBamboo.GrideEventType.Birth then
        --GameUtils.Toast(localize("出生点_TargetId_",{_TargetId_ = eventVo.id}))
    --关卡
    elseif type == ConstantsBamboo.GrideEventType.Quest or type == ConstantsBamboo.GrideEventType.Finish then
        self:RefeshCatState(ConstantsBamboo.CatState.Hit)
        --GameUtils.Toast(localize("关卡_TargetId_",{_TargetId_ = eventVo.id}))
        self:CheckQuestEvent(eventVo, grideVo)
    else
        self:RefeshCatState(ConstantsBamboo.CatState.Get)

        if checkString(grideVo._id) == checkString(self._lastTargetGride._id) then
            BambooQuestComponent:ActivityQuestMoveReq(self._moveHistory, eventVo.id, self._activityUuid, function()
                self._moveHistory = {}
                --清脚印
                self:ClearFootGo()
            end)
        else
            local isBoss = (checkNumber(eventVo.model) == ConstantsBamboo.GridShowType.BOSS)
            local bambooEventImageMapVo = BambooUtils.GetBambooEventImageMapVo(eventVo.model)
            local fPos = grideVo._grideGo.transform.position + Vector3(-ConstantsBamboo.GrideSideLength * 0.5, 0 -ConstantsBamboo.GrideSideLength * 0.5)
            local tPos = grideVo._grideGo.transform.position + Vector3(ConstantsBamboo.GrideSideLength * 0.5, 0 -ConstantsBamboo.GrideSideLength * 0.5)
    
            GameUtils.ThirdConfirm(eventVo.tips, bambooEventImageMapVo.icon, eventVo.tips, bambooEventImageMapVo.name, isBoss, tPos, fPos, function()
                BambooQuestComponent:ActivityQuestMoveReq(self._moveHistory, eventVo.id, self._activityUuid, function()
                    self._moveHistory = {}
                    --清脚印
                    self:ClearFootGo()
                end)
                end, function()
                    --GameUtils.Toast(localize("寻路失败"))
                    self:BackPathOriginGride()
                end, checkNumber(eventVo.openConfirm) ~= 1)
        end
        --[[
        BambooQuestComponent:ActivityQuestMoveReq(self._moveHistory, eventVo.id, self._activityUuid, function()
            self._moveHistory = {}
        end)
        ]]
    end
end

---CheckQuestEvent 处理一个关卡
---@param eventVo BambooEventVo @ 事件vo
function BambooMgr:CheckQuestEvent(eventVo, grideVo)
    if not eventVo then
        GameUtils.Toast(localize("未找到事件配置"))
        return
    end
    local questId = checkNumber(eventVo.regionId)
    if questId == 0 then
        GameUtils.Toast(localize("未找到关卡配置"))
        return
    end

    local bambooEventImageMapVo = BambooUtils.GetBambooEventImageMapVo(eventVo.model)
    local fPos = grideVo._grideGo.transform.position + Vector3(-ConstantsBamboo.GrideSideLength * 0.5, 0 -ConstantsBamboo.GrideSideLength * 0.5)
    local tPos = grideVo._grideGo.transform.position + Vector3(ConstantsBamboo.GrideSideLength * 0.5, 0 -ConstantsBamboo.GrideSideLength * 0.5)
    local vo = QuestConfMgr:GetInstance():GetQuestVoById(questId)
    if vo then
        Events.Broadcast("DestoryCommonTipsBord", nil)

        local isBoss = (checkNumber(eventVo.model) == ConstantsBamboo.GridShowType.BOSS)
        --剧情
        if checkNumber(vo.type) == Constants.QuestBattleType.Story then

            if checkString(grideVo._id) == checkString(self._lastTargetGride._id) then
                ---屏蔽点击
                self:ActiviteClick(false)
                self:PlayPlot(vo, function()
                    BambooQuestComponent:ActivityQuestPlotReq(questId, self._activityUuid, function()
                        BambooQuestComponent:ActivityQuestMoveReq(self._moveHistory, eventVo.id, self._activityUuid, function()
                            self._moveHistory = {}
                            --清脚印
                            self:ClearFootGo()
                        end, function()
                            --GameUtils.Toast(localize("寻路失败"))
                            self:BackPathOriginGride()
                        end)
                        self:ActiviteClick(true)
                    end)
                end)
            else
                GameUtils.ThirdConfirm(eventVo.tips, bambooEventImageMapVo.icon, eventVo.tips, bambooEventImageMapVo.name, isBoss, tPos, fPos, function()
                    ---屏蔽点击
                    self:ActiviteClick(false)
                    self:PlayPlot(vo, function()
                        BambooQuestComponent:ActivityQuestPlotReq(questId, self._activityUuid, function()
                            BambooQuestComponent:ActivityQuestMoveReq(self._moveHistory, eventVo.id, self._activityUuid, function()
                                self._moveHistory = {}
                                --清脚印
                                self:ClearFootGo()
                            end, function()
                                --GameUtils.Toast(localize("寻路失败"))
                                self:BackPathOriginGride()
                            end)
                            self:ActiviteClick(true)
                        end)
                    end)
                end, function()
                    self:BackPathOriginGride()
                end, checkNumber(eventVo.openConfirm) ~= 1)
            end
            --[[
            ---屏蔽点击
            self:ActiviteClick(false)
            self:PlayPlot(vo, function()
                BambooQuestComponent:ActivityQuestPlotReq(questId, self._activityUuid, function()
                    BambooQuestComponent:ActivityQuestMoveReq(self._moveHistory, eventVo.id, self._activityUuid, function()
                        self._moveHistory = {}
                    end, function()
                        --GameUtils.Toast(localize("寻路失败"))
                        self:BackPathOriginGride()
                    end)
                    self:ActiviteClick(true)
                end)
            end)
            ]]
        else

            if checkString(grideVo._id) == checkString(self._lastTargetGride._id) then
                if BambooUtils.IsCanBattle(self._activityUuid) then
                    cs_coroutine.start(function()
                        Events.Broadcast(Constants.EventNames.BamBooMgrClear, nil)
                        BambooQuestComponent:SetEntryQuest(true)
                        self:AddUIPage()
                        FightPreWarMgr:GetInstance():FightEnter(questId, {activityUuid = self._activityUuid, moveMap = self._moveHistory, eventId = eventVo.id})
                        --coroutine.yield(self:Clear())
                    end)
                else
                    GameUtils.Toast(localize("队伍成员已死亡"))
                end
            else
                GameUtils.ThirdConfirm(eventVo.tips, bambooEventImageMapVo.icon, eventVo.tips, bambooEventImageMapVo.name, isBoss, tPos, fPos, function()
                    if BambooUtils.IsCanBattle(self._activityUuid) then
                        cs_coroutine.start(function()
                            Events.Broadcast(Constants.EventNames.BamBooMgrClear, nil)
                            BambooQuestComponent:SetEntryQuest(true)
                            self:AddUIPage()
                            FightPreWarMgr:GetInstance():FightEnter(questId, {activityUuid = self._activityUuid, moveMap = self._moveHistory, eventId = eventVo.id})
                            --coroutine.yield(self:Clear())
                        end)
                    else
                        GameUtils.Toast(localize("队伍成员已死亡"))
                    end
                end, function()
                    --GameUtils.Toast(localize("寻路失败"))
                    self:BackPathOriginGride()
                end, checkNumber(eventVo.openConfirm) ~= 1)
            end
            --[[
            if BambooUtils.IsCanBattle(self._activityUuid) then
                cs_coroutine.start(function()
                    Events.Broadcast(Constants.EventNames.BamBooMgrClear, nil)
                    BambooQuestComponent:SetEntryQuest(true)
                    FightPreWarMgr:GetInstance():FightEnter(questId, {activityUuid = self._activityUuid, moveMap = self._moveHistory, eventId = eventVo.id})
                    --coroutine.yield(self:Clear())
                end)
            else
                GameUtils.Toast(localize("队伍成员已死亡"))
            end
            ]]
        end
    end
end

