function BambooMgr:AddUIPage()
    CS.Engine.UI.UIModule.AddUIPage({ id = Constants.UITypeIds.UIBambooCheckpointDialog, parameters = {activityUuid = self._activityUuid, mapId = self._mapId}})
end

--播放剧情
function BambooMgr:PlayPlot(vo, endCb)
    if not vo then
        return
    end
    if self._isPlayPlot then
        return
    end
    self._isPlayPlot = true
    local plotIds = CfUtils.Split(vo.plotId)
    if not plotIds then
        GameUtils.Toast(localize("该关卡没有剧情参数"))
        self._isPlayPlot = false
        return 
    end

    self._curPlotIndex = 1
    self:PlayPloting(plotIds, vo, endCb)
end

function BambooMgr:PlayPloting(plotIds, vo, endCb)
    ---@type ChapterUtils
    local ChapterUtils = import('Game.Chapter.ChapterUtils')
    --ChapterUtils.ProcessChapter(checkNumber(plotIds[self._curPlotIndex]), function(go)
    --    Events.Broadcast(Constants.EventNames.EventBambooMainStatus, {isTrue = false})
    --    self._plotGo = go
    --end, function()
    --    --所有的播完结束
    --    if self._curPlotIndex >= table.count(plotIds) then
    --        GameUtils.PlayMainBGM()
    --        if endCb then
    --            endCb()
    --        end
    --        Events.Broadcast(Constants.EventNames.EventBambooMainStatus, {isTrue = true})
    --        KTool.SafeDelete(self._plotGo)
    --        self._isPlayPlot = false
    --    else
    --        self._curPlotIndex = self._curPlotIndex + 1
    --        KTool.SafeDelete(self._plotGo)
    --        self:PlayPloting(plotIds, vo, endCb)
    --    end
    --end)
    local co = cs_coroutine.start(function()
        ::start::
        local wait = true
        ChapterUtils.ProcessChapter(checkNumber(plotIds[self._curPlotIndex]), function(go)
            Events.Broadcast(Constants.EventNames.EventBambooMainStatus, {isTrue = false})
            self._plotGo = go
        end, function()
            --所有的播完结束
            wait = false
        end)

        while wait do
            coroutine.yield()
        end

        KTool.SafeDelete(self._plotGo)

        --dispose
