---CompleteEvent 完成一个事件
---@param eventId number 事件id
function BambooMgr:CompleteEvent(eventId)
    eventId = checkNumber(eventId)
    if eventId <= 0 then
        return
    end

    local eventVo = BambooUtils.GetBambooEventVo(eventId)
    if not eventVo then
        return
    end

    --格子事件置空
    local grideIds = CfUtils.Split(eventVo.ceilId)
    if grideIds and table.count(grideIds) > 0 then
        for _, grideId in pairs(grideIds) do
            local grideVo = self:GetGrideVoById(grideId)
            self:RefreshGrideEventId(grideVo, ConstantsBamboo.GrideEventType.None)
        end
    end

    --事件触发效果
    local t = BambooUtils.GetEventEffects(eventId)
    if not t or table.count(t) <= 0 then
        return
    end

    for k, v in pairs(t) do
        self:ActivateEffect(v)
    end
end

---ActivateEffect 激活一个效果
---@param effectId number 效果id
function BambooMgr:ActivateEffect(effectId)
    local vo = BambooUtils.GetBambooEventEffectVo(effectId)
    if not vo then
        return 
    end
    local type = checkNumber(vo.changeType)
    --格子同行状态
    if type == ConstantsBamboo.EventEffectType.CanMove then
        local pointVo = BambooUtils.GetBambooMapPointVo(vo.changeTarget)
        self:RefreshGrideStatus(pointVo, vo.changeNum, true)
    --模型显示隐藏
    elseif type == ConstantsBamboo.EventEffectType.ShowModel then
        local eventVo = BambooUtils.GetBambooEventVo(vo.changeTarget)
        if eventVo then
            local grideIds = CfUtils.Split(eventVo.ceilId)
            if grideIds and table.count(grideIds) > 0 then
                local grideVo = self:GetGrideVoById(grideIds[1])
                self:RefreshGrideModelStatus(grideVo, vo.changeNum, self:GetEventGoPath(eventVo.id))
            end
        end
    --激活事件
    elseif type == ConstantsBamboo.EventEffectType.ActivityEvent then
        local eventVo = BambooUtils.GetBambooEventVo(vo.changeTarget)
        if eventVo then
            --该事件所有的格子
            local grideIds = CfUtils.Split(eventVo.ceilId)
            if grideIds and table.count(grideIds) > 0 then
                for _, grideId in pairs(grideIds) do
                    local grideVo = self:GetGrideVoById(grideId)
                    if checkNumber(vo.changeNum) == ConstantsBamboo.EffectEventStatus.Create then
                        self:RefreshGrideEventId(grideVo, eventVo.id)
                    else
                        self:RefreshGrideEventId(grideVo, ConstantsBamboo.GrideEventType.None)
                    end
                end
            end
        end
    end
end

--事件完成后模型的动画
function BambooMgr:PlayEventFinishAni()
    local eventId = BambooQuestComponent._lastEventId
    BambooQuestComponent._lastEventId = 0

    local effets = BambooUtils.GetEventEffects(eventId)
    if not effets or table.count(effets) <= 0 then
        return
    end

    local t = {}
    for k, v in pairs(effets) do
        local vo = BambooUtils.GetBambooEventEffectVo(v)
        if vo then
            if vo.changeType == ConstantsBamboo.EventEffectType.ShowModel then
                table.insert(t, vo.changeTarget)    
            end
        end
    end
    if table.count(t) <= 0 then
        return
    end

    for k, v in pairs(t) do
        local eventVo = BambooUtils.GetBambooEventVo(v)
        if eventVo then
            local go = self:GetModelGo(self:GetEventGoPath(eventVo.id))
            KTool.SetActive(go, false)

            if go then
                local grideIds = CfUtils.Split(eventVo.ceilId)
                if grideIds and table.count(grideIds) > 0 then
                    local grideVo = self:GetGrideVoById(grideIds[1])
                    if grideVo then
                        KTool.SetParent(go, grideVo._grideGo, false)
                        go.transform.localPosition = Vector3(0 - ConstantsBamboo.PosOff * math.cos(ConstantsBamboo.OffZ * Mathf.Deg2Rad), 0, 0 - ConstantsBamboo.PosOff)
                        KTool.SetActive(go, true)
                    end
                end

                local ani = go:GetComponent("Animator")
                if not IsNull(ani) then
                    if not self._cos then
                        self._cos = {}
                   end
                   local co = cs_coroutine.start(function()
                       CfUtils.PlayAnimator(ani, "Exit")
                       cs_coroutine.yield_return(Yielders.GetWaitForSeconds(1.5))
                       self:PullModelPool(self:GetEventGoPath(eventVo.id), nil, go)
                   end)
                   table.insert(self._cos, co)
                else
                    self:PullModelPool(self:GetEventGoPath(eventVo.id), nil, go)
                end
            end
        end
    end
end

---RefreshGrideStatus 刷新格子通行状态 
---@param pointVo table BambooMapPointVo
---@param type number 修改类型
---@param isRefreshAstarMap boolean 是否刷新astar的map
function BambooMgr:RefreshGrideStatus(pointVo, status, isRefreshAstarMap)
    if not pointVo then
        return
    end

    status = checkNumber(status)
    if not self._obstacles then 
        self._obstacles = {}
    end

    local t = self._obstacles[checkString(pointVo.posY)]
    if not t then
        self._obstacles[checkString(pointVo.posY)] = {}
        t = self._obstacles[checkString(pointVo.posY)]
    end

    if status == ConstantsBamboo.GrideStatus.OBSTACLES then
        table.insert(t, pointVo.posX)
    elseif status == ConstantsBamboo.GrideStatus.NONE then
        table.removebyvalue(t, pointVo.posX)
    end
    local grideVo = self:GetGrideVoById(pointVo.id)
    if grideVo then
        grideVo._status = status
    end

    if isRefreshAstarMap then
        AStarMgr:GetInstance():RefreshDisablePoints(self._obstacles)
    end
end

---RefreshGrideModelStatus 刷新格子上的模型状态 
---@param grideVo table BambooMapPointVo
---@param status number 修改类型
function BambooMgr:RefreshGrideModelStatus(grideVo, status, modelPath)
    if not grideVo then
        return
    end

    status = checkNumber(status)
    if status == ConstantsBamboo.GrideModelStatus.Hide then
        self:PullModelPool(modelPath, grideVo)
    elseif status == ConstantsBamboo.GrideModelStatus.Show then
        self:SetGrideGo(grideVo, modelPath)
    end
end

