---SetGrideGo 设置格子的模型 
---@param grideVo table BambooMapPointVo
---@param path string 
function BambooMgr:SetGrideGo(grideVo, path)
    if not grideVo or string.isEmpty(path) then
        return
    end
    --[[
    if grideVo._grideModelGo then
        self:PullModelPool(go)
    end
    ]]
    local go = self:GetModelGo(path)
    if go then
        KTool.SetParent(go, grideVo._grideGo, false)
        grideVo._grideModelGo = go

        UIEventProxy.Create(go.gameObject).onPointerClick = function(eventData)
            self:ClickGride(grideVo._id)
        end 
        
        KTool.SetActive(go, true)
        go.transform.localPosition = Vector3(0 - ConstantsBamboo.PosOff * math.cos(ConstantsBamboo.OffZ * Mathf.Deg2Rad), 0, 0 - ConstantsBamboo.PosOff)
    end
end

