---GetModelGo 获取一个模型
---@param path string 模型路径
function BambooMgr:GetModelGo(path)
    path = checkString(path)
    if string.isEmpty(path) then
        return
    end
    if not self._modelPool then
        self._modelPool = {}
    end

    local t = self._modelPool[path]
    local go
    if t and #t > 0 then
       go = t[#t]
       table.remove(t, #t)
    else
        local loader = self:GetLoader(path)
        if loader.IsSuccess then
            go = CfUtils.InstantiateGo(loader.ResultObject)
        end
    end
    return go
end

---PullModelPool 放入对象池
---@param path string 模型路径
---@param grideVo BambooMapGrideVo
function BambooMgr:PullModelPool(path, grideVo, modelGo)
    path = checkString(path)
    if string.isEmpty(path) then
        return
    end
    if not self._modelPool then
        self._modelPool = {}
    end

    local t = self._modelPool[path]
    if not t then
        self._modelPool[path] = {}
        t = self._modelPool[path]
    end
    if grideVo then
        KTool.SetActive(grideVo._grideModelGo, false)
        table.insert(t, grideVo._grideModelGo)
        grideVo._grideModelGo = nil
    end
    if modelGo then
        KTool.SetActive(modelGo, false)
        table.insert(t, modelGo)
    end
end

--波次改变
function BambooMgr:OnBambooWaveChange(body)
    if not body then 
        return
    end

    body = checkTable(body)

    local eventVo = BambooUtils.GetBambooEventVo(body.eventId)
    if not eventVo then
        return
    end
    --结束
    if checkNumber(eventVo.type) == ConstantsBamboo.GrideEventType.Finish then
        self._isFinish = true
        Events.Broadcast(Constants.EventNames.EventBambooMainStatus, {isTrue = true})
        return
    end

    --处理事件
    self:CompleteEvent(body.eventId)

    if checkNumber(eventVo.type) ~= ConstantsBamboo.GrideEventType.Quest and checkNumber(eventVo.type) ~= ConstantsBamboo.GrideEventType.None and checkNumber(eventVo.type) ~= ConstantsBamboo.GrideEventType.Birth then
        self:PlayEventFinishAni()
    end

    --处理波次
    local lastWave = body.lastWave
    local curWave = body.curWave

    --改变才刷新
    if curWave > lastWave then
        self:RefreshMapEvents(lastWave + 1, curWave)
    end
end

--启动红点计时器   !!这个计时器只会使节点变为开启状态
function BambooMgr:HandleStateTimeDown()
    self._tiemDown = CDTimerModule.GetInstance():AddCD(1, function(count, id)
        self._waitTime = self._waitTime + 1
        if self._waitTime == 5 then
            self:RefeshCatState(ConstantsBamboo.CatState.Idle3)
        end
    end, 2592000, false, true)
end

function BambooMgr:RefeshCatState(state)
    if self._spinCo then
        cs_coroutine.stop(self._spinCo)
        self._spinCo = nil
    end

    if not self._playerGo then
        return
    end
    if isNull(self._catAni) then
        return
    end
    self._spinCo = cs_coroutine.start(function()
        --CfUtils.FillText(self.NpcTalk, talk)
        if state == ConstantsBamboo.CatState.Idle1 then
            self._catAni:TryPlay('idle')
            --CfUtils.PlaySpine(self._playerGo, "idle1", true)
            self._waitTime = 0
        elseif state == ConstantsBamboo.CatState.Idle3 then
            self._catAni:TryPlay('idle_2')
            --CfUtils.PlaySpine(self._playerGo, "idle2", false)
            --coroutine.yield(WaitForSeconds(CfUtils.GetSpineTime(self._playerGo, "idle2")))
            --CfUtils.PlaySpine(self._playerGo, "idle3", true)
        elseif state == ConstantsBamboo.CatState.Run then
            --CfUtils.PlaySpine(self._playerGo, "run", true)
            self._catAni:TryPlay('run')
        elseif state == ConstantsBamboo.CatState.Get then
            self._catAni:TryPlay('touch1')
            coroutine.yield(WaitForSeconds(2))
            --CfUtils.PlaySpine(self._playerGo, "get", false)
            --coroutine.yield(WaitForSeconds(CfUtils.GetSpineTime(self._playerGo, "get")))
            --CfUtils.PlaySpine(self._playerGo, "idle1", true)
            self._waitTime = 0
        elseif state == ConstantsBamboo.CatState.Hit then
            self._catAni:TryPlay('touch1')
            coroutine.yield(WaitForSeconds(2))
           --CfUtils.PlaySpine(self._playerGo, "hit", false)
            --coroutine.yield(WaitForSeconds(CfUtils.GetSpineTime(self._playerGo, "hit")))
            --CfUtils.PlaySpine(self._playerGo, "idle1", true)
            self._waitTime = 0
        elseif state == ConstantsBamboo.CatState.Stop then
            self._catAni:TryPlay('stop')
            if not isNull(self._stopUIGo) then
                local cam = self._bambooCam.gameObject:GetComponent(typeof(Camera))
                local pos = CfUtils.WorldPosition2UIPosition(self._catAni.transform.position, self._stopUIGo.transform.parent.transform, cam)
                self._stopUIGo.transform.localPosition = Vector3(pos.x, pos.y + 130, 0)
                CfUtils.SetActive(self._stopUIGo, true)
            end

            coroutine.yield(WaitForSeconds(2))
            CfUtils.SetActive(self._stopUIGo, false)
            --CfUtils.PlaySpine(self._playerGo, "stop", false)
            --coroutine.yield(WaitForSeconds(CfUtils.GetSpineTime(self._playerGo, "stop")))
            --CfUtils.PlaySpine(self._playerGo, "idle1", true)
            self._catAni:TryPlay('idle')
            self._waitTime = 0
        end
    end)
end 

