function BambooMgr:ClearMoveTween()
    if self._moveTween then
        self._moveTween:Kill(true)
        self._moveTween = nil
    end
end

function BambooMgr:Clear()
    cs_coroutine.start(function()
        if not isNull(self._loaders) then
            for k, v in pairs(self._loaders) do
                v:Release(true)
                v = nil
            end
        end
        if self._spinCo then
            cs_coroutine.stop(self._spinCo)
            self._spinCo = nil
        end
        if not isNull(self._tiemDown) then
            CDTimerModule.GetInstance():RemoveCD(self._tiemDown)
            self._tiemDown = nil
        end
        if self._cos then
            for k, v in pairs(self._cos) do
                cs_coroutine.stop(v)
            end
        end

        self:ClearMoveTween()
        self:ClearMoveCo()
        AStarMgr:GetInstance():Clear()
        --Events.Broadcast(Constants.EventNames.UIMainHomeSceneFocusShowEventName, true)
        self:UnloadBambooScene()
        --sceneManagement:UnloadAppendedSceneById(BambooSceneId)
    end)

    self:__delete()
    self.Destroy(self)
end

---新增活动体力相关逻辑
---购买活动体力
function BambooMgr:BuyActivityHp()
    if BambooQuestComponent:IsAcrivityEnd(BambooQuestComponent._curactivityUuid) then
        GameUtils.Toast(localize("活动已结束"))
        return
    end
    local maxLimit = BambooQuestComponent.hpParams.hpUpLimit
    local num = BambooQuestComponent.hpParams.buyNum
    local consumeGoodsId =  BambooQuestComponent.hpParams.buyConsumeItem
    local consumeNums = BambooQuestComponent.hpParams.buyConsumeItemNum
    local buyTimes = BambooQuestComponent.hpData.dailyBuyHpTimes
    local maxBuyLimit = BambooQuestComponent.hpParams.buyDailyTimeLimit
    local maxBuyNum = 1
    if checkInt(buyTimes) >= checkInt(maxBuyLimit) then
        maxBuyNum = 0
    end
    local consumeNum = consumeNums[buyTimes + 1] or consumeNums[#consumeNums]
    local prices = {{currency = checkInt(consumeGoodsId), current = checkInt(consumeNum)}}
    local activityTips = localize('今日剩余兑换次数: _num_', {_num_ = checkInt(maxBuyLimit) - buyTimes})
    local consume = {goodsId = consumeGoodsId, num = consumeNum}

    local UIModule = CS.Engine.UI.UIModule
    UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonBuyItemDialog, parameters = {
        goodsId        = Constants.Currency.BambooHp,
        goodsNum       = num,
        isShowNum      = true,
        maxHaveNum     = checkInt(maxLimit),
        prices         = prices,
        maxBuyNum      = maxBuyNum,
        activityTips   = activityTips,
        buyCb          = function (price, buyNum)
            GameUtils.Request(Interfaces.ActivityQuestPtBuyHp, {consume = table.serialize(consume), activityUuid = BambooQuestComponent._curactivityUuid}, function(request, response)
                local showRewards = clone(response.data.rewards)
                table.insert(response.data.rewards, {
                    goodsId = consumeGoodsId,
                    num = -consumeNum
                })
                GoodsUtils.DrawRewards(response.data.rewards, true)
                local hpInfo = checkTable(response.data.hpInfo)
                BambooQuestComponent.hpData.hp = hpInfo.hp
                BambooQuestComponent.hpData.lastCdTime = hpInfo.lastCdTime
                BambooQuestComponent.hpData.dailyBuyHpTimes = BambooQuestComponent.hpData.dailyBuyHpTimes + 1
                UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = showRewards } })
            end)
        end
    }})
end


function BambooMgr:ShowTipsCountDown(targetNode, title, description, rare, id, isShowNumText)
    local UIModule = CS.Engine.UI.UIModule
    ResourceModule.LoadGameObjectAsync("Prefabs/Bamboo120101/BambooHpTips120101.prefab", function(go)
        if not KTool.IsNull(go) and not KTool.IsNull(targetNode) then
            go.name = "BambooHpTipsCountdown"
            if not KTool.IsNull(go) and not KTool.IsNull(targetNode) then
