                    script.Env:RefreshBoardByContent(title, description, rare, id, isShowNumText)
                    script.Env:FixBoardPosition(targetNode)
                end
            end
        end
    end, true, UIModule.RootCanvas.transform)
end

---开启定时器
function BambooMgr:StartTimer()
    self:CloseTimer()
    self.timer = CDTimerModule.GetInstance():AddCD(1, function(_, _, delta)
        -- 体力已经恢复满，停止倒计时
        if self:IsHPFull() then
            BambooQuestComponent.hpData.lastCdTime = 0
            self:BroadcastHPChangeEvent(true, 0, 0)
            self:CloseTimer()
            return
        end
        
        self:SubCDTime(delta)

    end, CountDownTime, true, true)
end

---移除定时器
function BambooMgr:CloseTimer()
    if isNotNull(self.timer) then
        CDTimerModule.GetInstance():RemoveCD(self.timer)
        self.timer = nil
    end
end

---定时器处理
function BambooMgr:SubCDTime(delta)
    BambooQuestComponent.hpData.lastCdTime = checkNumber(BambooQuestComponent.hpData.lastCdTime) - checkNumber(delta)
    -- 通知注册者数值发生了变化
    local goodsNum = GoodsUtils.GetThingNo(Constants.Currency.BambooHp)
    local max = BambooQuestComponent.hpParams.hpUpLimit
    local hpRecoverSeconds = BambooQuestComponent.hpParams.restoreHpInterval
    local recoveryHpPerTime = BambooQuestComponent.hpParams.restoreNum
    self:BroadcastHPChangeEvent(false, checkInt(BambooQuestComponent.hpData.lastCdTime), checkInt(BambooQuestComponent.hpData.lastCdTime + (max - goodsNum - 1) * checkInt(hpRecoverSeconds)))
    if BambooQuestComponent.hpData.lastCdTime < 0 then
        -- 开始恢复体力
        local mod = (math.abs(BambooQuestComponent.hpData.lastCdTime) - 1) % recoveryHpPerTime    -- 溢出mod秒
        local left = (math.abs(BambooQuestComponent.hpData.lastCdTime) - 1) / recoveryHpPerTime   -- 溢出left体力
        local recoverCount = (left + 1) * recoveryHpPerTime

        --printInfo("CHANG DEBUG：实际恢复的体力:" .. checkString(recoverCount))
        GoodsUtils.DrawRewards({
            {
                goodsId = Constants.Currency.BambooHp,
                num = recoverCount
            }
        }, true)

        -- 重置倒计时
        BambooQuestComponent.hpData.lastCdTime = hpRecoverSeconds - mod
        self:StartTimer()
    end
end

---广播hp变动事件
function BambooMgr:BroadcastHPChangeEvent(isFull, cd, totalCD)
    if Events.HasListener(Constants.EventNames.BamBooHpChange) then
        Events.Broadcast(Constants.EventNames.BamBooHpChange, isFull, cd, totalCD)
    end
end

function BambooMgr:IsHPFull()
    local curCount = checkNumber(GoodsUtils.GetThingNo(Constants.Currency.BambooHp))
    return curCount >= BambooQuestComponent.hpParams.hpUpLimit
end

return BambooMgr
